  "hujeta-gar": [{"flag":"eatsShrimp","confidence":"explicit","condition":"Canlı nehir karidesi yem olarak önerilir; cüce karidesler doğrudan av riski altındadır.","evidence":"Seriously Fish, yetişkinlere verilecek yemler arasında canlı nehir karidesini sayar; tür karidesi canlı av olarak yer.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/ctenolucius-hujeta/","verifiedAt":"2026-09-28"}],
