  "jewel-cichlid": [{"flag":"conspecificAggression","value":"all","confidence":"explicit","condition":"Çift, gençlerden oluşan bir gruptan doğal eşleşmeyle kurulmalı.","evidence":"Çift halinde tutulmalı; ancak rastgele alınan bir çiftte zayıf birey genellikle öldürülür.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/hemichromis-bimaculatus/","verifiedAt":"2026-09-28"}],
  "johanni-cichlid": [{"flag":"conspecificAggression","value":"males","confidence":"explicit","condition":"Erkek başına birkaç dişi.","evidence":"Erkekler hemcinslerine karşı saldırgan ve bölgeci; birden fazla erkek için büyük tank gerekir.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/melanochromis-johanni/","verifiedAt":"2026-09-28"}],
  "kissing-gourami": [{"flag":"conspecificAggression","value":"all","confidence":"explicit","condition":"Büyük akvaryumda aynı anda eklenen gençlerden grup mümkün (Fishkeeper de büyük akvaryumda grup öneriyor); yerleşik bireye sonradan balık eklenmemeli.","evidence":"Küçük akvaryumda baskın birey hemcinslerini ölümüne taciz edebilir; asla yalnızca iki tane alınmamalı.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/helostoma-temminkii/","verifiedAt":"2026-09-28"}],
  "koi-carp": [{"flag":"eatsSnails","confidence":"explicit","evidence":"PFK (Jeremy Gay), koi'lerin de Physa salyangozlarını iyi avladığını yazar.","source":"Practical Fishkeeping","sourceUrl":"https://www.practicalfishkeeping.co.uk/features/problem-solver-snails/","verifiedAt":"2026-09-28"}],
  "kribensis": [{"flag":"conspecificAggression","value":"all","confidence":"explicit","condition":"Birden fazla çift yalnızca büyük tankta.","evidence":"Çift halinde tutulmalı; birden fazla çift için büyük tank gerekir. Üremede çok bölgecileşir.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/pelvicachromis-pulcher/","verifiedAt":"2026-09-28"}],
  "kuhli-loach": [{"flag":"eatsShrimp","confidence":"explicit","condition":"Yavru karidesleri neredeyse kesin yer; yoğun bitkili akvaryumda yetişkinlerle birlikte tutulabilmiştir.","evidence":"PFK (Nathan Hill), kuhli çöpçülerini 'belki' grubunda sayar; bu grup yavru karidesleri neredeyse kesin yer. PFK (Ade Dunn) ise kuhli çöpçüleriyle karidesleri yoğun bitkili bir akvaryumda birlikte tuttuğunu yazar.","source":"Practical Fishkeeping","sourceUrl":"https://www.practicalfishkeeping.co.uk/features/what-can-i-keep-with-shrimp/","additionalSourceUrls":["https://www.practicalfishkeeping.co.uk/features/frequently-asked-questions-on-neocaridina-shrimps/"],"verifiedAt":"2026-09-28"}],
  "least-killifish": [{"flag":"shrimpSafe","confidence":"explicit","evidence":"Seriously Fish, benzer boydaki yırtıcı olmayan türler (kalem balığı, cüce Corydoras, Otocinclus) ile tatlı su karideslerini bu türün en iyi akvaryum arkadaşları olarak sayar.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/heterandria-formosa/","verifiedAt":"2026-09-28"}],
  "leleupi-cichlid": [{"flag":"conspecificAggression","value":"all","confidence":"explicit","condition":"Çok büyük tank hariç.","evidence":"Hemcinslerine çok saldırgan; tank çok büyük değilse yalnızca tek çift tutulmalı.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/neolamprologus-leleupi/","verifiedAt":"2026-09-28"}],
  "livingstonii-cichlid": [{"flag":"conspecificAggression","value":"males","confidence":"explicit","condition":"Tek birey veya tek erkekli harem.","evidence":"Doğada yalnız yaşar; tek birey olarak ya da üreme için tek erkek ve birkaç dişiden oluşan harem halinde tutulmalı.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/nimbochromis-livingstonii/","verifiedAt":"2026-09-28"}],
  "maingano-cichlid": [{"flag":"conspecificAggression","value":"males","confidence":"explicit","condition":"Kalabalık mbuna düzeni.","evidence":"Kendi türünden bireylere toleranssız; erkek başına birkaç dişi tutulmalı.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/melanochromis-cyaneorhabdos/","verifiedAt":"2026-09-28"}],
  "manacapuru-bristlenose-l148": [{"flag":"shrimpSafe","confidence":"explicit","condition":"Kaynak ifadesi cins düzeyindedir (Ancistrus); olgun, yoğun bitkili akvaryumda, yavruların bir kısmı hayatta kalır.","evidence":"PFK, Ancistrus cinsinin barışçıl olduğunu, pek çok akvaryumcunun onları tatlı su karidesi kolonileriyle birlikte tuttuğunu ve olgun, yoğun bitkili akvaryumlarda bazı yavru karideslerin hayatta kaldığını yazar.","source":"Practical Fishkeeping","sourceUrl":"https://www.practicalfishkeeping.co.uk/features/bristlenose-catfish-the-hardworking-ancistrus/","verifiedAt":"2026-09-28"}],
  "marliers-julie": [{"flag":"conspecificAggression","value":"all","confidence":"explicit","condition":"Devasa tank hariç.","evidence":"Yetişkinler birbirine çok kavgacı; tank devasa değilse çift olarak tutulmalı.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/julidochromis-marlieri/","verifiedAt":"2026-09-28"}],
  "medaka": [{"flag":"shrimpSafe","confidence":"explicit","condition":"Kaynak ifadesi grup düzeyindedir (pirinç balıkları / Oryzias); tür adı geçmez.","evidence":"PFK (Neale Monks), pirinç balıklarının (ricefish) karideslere hiç tehdit oluşturmadığını, kendi yavrularını bile görmezden gelen yüzey beslenicileri olduğunu yazar.","source":"Practical Fishkeeping","sourceUrl":"https://www.practicalfishkeeping.co.uk/fishkeeping-answers/can-i-safely-add-some-shrimp/","verifiedAt":"2026-09-28"}],
