  "sparkling-gourami": [{"flag":"eatsShrimp","confidence":"explicit","condition":"Yavru karidesleri yer; yetişkinleri çoğunlukla yalnızca kabuk değişimi sonrası avlar. Kaynak Amano karidesini alternatif önerir.","evidence":"PFK, sparkling guraminin mükemmel bir karides avcısı olduğunu; yetişkin karidesi genellikle yalnızca kabuk değişimi sonrası avladığını, yavru karideslerin ise atıştırmalık olacağını yazar. Seriously Fish bazı akvaryumcuların küçük Caridina/Neocaridina karideslerini avladığını bildirdiğini belirtir; PFK nano listesi de küçük süs karideslerini yiyeceğini yazar.","source":"Practical Fishkeeping","sourceUrl":"https://www.practicalfishkeeping.co.uk/features/everything-you-need-to-know-about-the-brilliantly-bright-sparkling-gou/","additionalSourceUrls":["https://www.seriouslyfish.com/species/trichopsis-pumila/","https://www.practicalfishkeeping.co.uk/features/top-10-small-fish-for-nano-aquariums/"],"verifiedAt":"2026-09-28"}],
  "spotted-congo-puffer": [{"flag":"finNipper","confidence":"explicit","evidence":"Kaynak türün, tüm balon balıklarında olduğu gibi, uygun olmayan tank arkadaşlarını ısırabileceğini belirtiyor.","source":"Fishkeeper","sourceUrl":"https://www.fishkeeper.co.uk/fish/freshwater/miscellaneous/spotted-congo-puffer","verifiedAt":"2026-09-28"},{"flag":"eatsShrimp","confidence":"explicit","condition":"Canlı karides yem olarak verilir.","evidence":"Fishkeeper, bu balon balığına yem olarak verilecek salyangoz ve canlı karideslerin önceden kuru yemle beslenebileceğini yazar.","source":"Fishkeeper","sourceUrl":"https://www.fishkeeper.co.uk/fish/freshwater/miscellaneous/spotted-congo-puffer","verifiedAt":"2026-09-28"},{"flag":"eatsSnails","confidence":"explicit","evidence":"Fishkeeper, bazı akvaryumcuların bu balon balığını beslemek için ayrı bir nano akvaryumda küçük salyangoz ürettiğini yazar.","source":"Fishkeeper","sourceUrl":"https://www.fishkeeper.co.uk/fish/freshwater/miscellaneous/spotted-congo-puffer","verifiedAt":"2026-09-28"}],
  "spotted-rasbora": [{"flag":"shrimpSafe","confidence":"explicit","condition":"Yalnızca en küçük yeni doğan karidesler risk altında; bitkili düzen önerilir.","evidence":"Seriously Fish, bitkili bir düzende Caridina ve Neocaridina karidesleriyle birlikte tutulabileceğini yazar. PFK (Nathan Hill) Boraras cinsini karides için güvenli balıklar arasında sayar: ağızları çok küçüktür, kayıp olursa yalnızca en küçük yavrular etkilenir.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/boraras-maculatus/","additionalSourceUrls":["https://www.practicalfishkeeping.co.uk/features/what-can-i-keep-with-shrimp/"],"verifiedAt":"2026-09-28"}],
