  "tire-track-eel": [{"flag":"eatsShrimp","confidence":"explicit","condition":"Kaynak ifadesi grup düzeyindedir (dikenli yılan balıkları).","evidence":"PFK (Nathan Hill), dikenli yılan balıklarının karides atıştırmayı sevdiğini ve karideslerle tutulmaması gereken gruplar arasında olduğunu yazar.","source":"Practical Fishkeeping","sourceUrl":"https://www.practicalfishkeeping.co.uk/features/what-can-i-keep-with-shrimp/","verifiedAt":"2026-09-28"},{"flag":"conspecificAggression","value":"all","confidence":"explicit","condition":"5 ya da daha fazla bireyle saldırganlık bazen önlenebilir.","evidence":"Hemcinslerine saldırgan olabileceğinden tank başına tek birey önerilir. Not: Seriously Fish bu cümlede \"fire eel\" adını kullanıyor; sayfa Mastacembelus armatus türüne ait.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/mastacembelus-armatus/","verifiedAt":"2026-09-28"}],
